"""
    from https://scientific-python-101.readthedocs.io/python/exercises/prime_factorization.html

    Return the prime factorization of `n`.

    Parameters
    ----------
    n : int
        The number for which the prime factorization should be computed.

    Returns
    -------
    dict[int, int]
        List of tuples containing the prime factors and multiplicities of `n`.

    """
def prime_factorization(n: Any) -> object {
    prime_factors = {};
    i = 2;
    while ((i ** 2) <= n) {
        if (n % i) {
            i += 1;
        } else {
            n /= i;
            try {
                prime_factors[i] += 1;
            } except KeyError {
                prime_factors[i] = 1;
            }
        }
    }
    if (n > 1) {
        try {
            prime_factors[n] += 1;
        } except KeyError {
            prime_factors[n] = 1;
        }
    }
    return prime_factors;
}

